#!/usr/bin/env bats
# BATS test suite for defensive Bash scripts
# Requires: bats-core (https://github.com/bats-core/bats-core)

# Setup test environment
setup() {
    # Create temporary test directories
    export TEST_DIR="$(mktemp -d)"
    export SOURCE_DIR="${TEST_DIR}/source"
    export BACKUP_DIR="${TEST_DIR}/backup"

    mkdir -p "${SOURCE_DIR}" "${BACKUP_DIR}"

    # Create test files
    echo "test content" > "${SOURCE_DIR}/testfile.txt"
    mkdir -p "${SOURCE_DIR}/subdir"
    echo "nested content" > "${SOURCE_DIR}/subdir/nested.txt"

    # Get script directory
    export SCRIPT_DIR="$(cd "$(dirname "${BATS_TEST_FILENAME}")" && pwd)"
}

# Cleanup after each test
teardown() {
    if [[ -n "${TEST_DIR}" && -d "${TEST_DIR}" ]]; then
        rm -rf "${TEST_DIR}"
    fi
}

# Test common_utils.sh functions
@test "common_utils.sh: logging functions exist" {
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"

    # Check that functions are defined
    declare -f log_error >/dev/null
    declare -f log_warn >/dev/null
    declare -f log_info >/dev/null
    declare -f log_debug >/dev/null
}

@test "common_utils.sh: die function exits with correct code" {
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"

    run die 42 "Test error message"

    [[ "${status}" -eq 42 ]]
    [[ "${output}" =~ "Test error message" ]]
}

@test "common_utils.sh: command_exists detects valid commands" {
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"

    command_exists "bash"
    command_exists "ls"
}

@test "common_utils.sh: command_exists fails for invalid commands" {
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"

    run command_exists "nonexistent_command_xyz"

    [[ "${status}" -ne 0 ]]
}

@test "common_utils.sh: validate_directory succeeds for valid directory" {
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"

    validate_directory "${SOURCE_DIR}"
}

@test "common_utils.sh: validate_directory fails for nonexistent directory" {
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"

    run validate_directory "${TEST_DIR}/nonexistent"

    [[ "${status}" -eq 2 ]]
}

@test "common_utils.sh: ensure_directory creates directory" {
    # shellcheck source=test/common_utils.sh
    source "${SCRIPT_DIR}/common_utils.sh"

    local new_dir="${TEST_DIR}/newdir"

    ensure_directory "${new_dir}"

    [[ -d "${new_dir}" ]]
}

@test "safe_backup.sh: script exists and is executable" {
    [[ -x "${SCRIPT_DIR}/safe_backup.sh" ]]
}

@test "safe_backup.sh: shows usage with -h flag" {
    run "${SCRIPT_DIR}/safe_backup.sh" -h

    [[ "${status}" -eq 0 ]]
    [[ "${output}" =~ "Usage:" ]]
}

@test "safe_backup.sh: requires source directory" {
    run "${SCRIPT_DIR}/safe_backup.sh" -b "${BACKUP_DIR}"

    [[ "${status}" -eq 2 ]]
    [[ "${output}" =~ "Source directory is required" ]]
}

@test "safe_backup.sh: requires backup directory" {
    run "${SCRIPT_DIR}/safe_backup.sh" -s "${SOURCE_DIR}"

    [[ "${status}" -eq 2 ]]
    [[ "${output}" =~ "Backup directory is required" ]]
}

@test "safe_backup.sh: creates backup archive" {
    run "${SCRIPT_DIR}/safe_backup.sh" -s "${SOURCE_DIR}" -b "${BACKUP_DIR}"

    [[ "${status}" -eq 0 ]]
    [[ "${output}" =~ "Backup completed successfully" ]]

    # Check that backup file was created
    local backup_count
    backup_count=$(find "${BACKUP_DIR}" -name "source_*.tar.gz" | wc -l)
    [[ "${backup_count}" -eq 1 ]]
}

@test "safe_backup.sh: backup archive contains source files" {
    "${SCRIPT_DIR}/safe_backup.sh" -s "${SOURCE_DIR}" -b "${BACKUP_DIR}" -q

    # Find the created backup
    local backup_file
    backup_file=$(find "${BACKUP_DIR}" -name "source_*.tar.gz" | head -n1)

    [[ -f "${backup_file}" ]]

    # List archive contents
    run tar -tzf "${backup_file}"

    [[ "${status}" -eq 0 ]]
    [[ "${output}" =~ "testfile.txt" ]]
    [[ "${output}" =~ "subdir/nested.txt" ]]
}

@test "safe_backup.sh: cleans up old backups" {
    # Create an old backup file
    local old_backup="${BACKUP_DIR}/source_20200101_000000.tar.gz"
    touch "${old_backup}"

    # Make it appear old
    touch -t 202001010000 "${old_backup}"

    # Run backup with 1-day retention
    "${SCRIPT_DIR}/safe_backup.sh" -s "${SOURCE_DIR}" -b "${BACKUP_DIR}" -k 1 -q

    # Old backup should be removed
    [[ ! -f "${old_backup}" ]]
}

@test "safe_backup.sh: validates source directory exists" {
    run "${SCRIPT_DIR}/safe_backup.sh" -s "${TEST_DIR}/nonexistent" -b "${BACKUP_DIR}"

    [[ "${status}" -eq 2 ]]
    [[ "${output}" =~ "does not exist" ]]
}

@test "safe_backup.sh: accepts verbose flag" {
    run "${SCRIPT_DIR}/safe_backup.sh" -s "${SOURCE_DIR}" -b "${BACKUP_DIR}" -v

    [[ "${status}" -eq 0 ]]
    [[ "${output}" =~ "DEBUG" ]]
}

@test "safe_backup.sh: accepts quiet flag" {
    run "${SCRIPT_DIR}/safe_backup.sh" -s "${SOURCE_DIR}" -b "${BACKUP_DIR}" -q

    [[ "${status}" -eq 0 ]]
    # Should have minimal output in quiet mode
    [[ ! "${output}" =~ "INFO" ]]
}

@test "safe_backup.sh: validates keep days is numeric" {
    run "${SCRIPT_DIR}/safe_backup.sh" -s "${SOURCE_DIR}" -b "${BACKUP_DIR}" -k "invalid"

    [[ "${status}" -eq 2 ]]
    [[ "${output}" =~ "must be a positive integer" ]]
}

